table|activity_log|CREATE TABLE activity_log ( id TEXT PRIMARY KEY, workspace_id TEXT, actor TEXT NOT NULL, project_id TEXT, action TEXT NOT NULL, notes TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|ai_cost_ledger|CREATE TABLE ai_cost_ledger ( id TEXT PRIMARY KEY, workspace_id TEXT, caller TEXT NOT NULL, model TEXT NOT NULL, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, cache_read_tokens INTEGER NOT NULL DEFAULT 0, cache_write_tokens INTEGER NOT NULL DEFAULT 0, cost_usd_micro INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) )
table|behavior_rules|CREATE TABLE behavior_rules ( id TEXT PRIMARY KEY, workspace_id TEXT, condition TEXT NOT NULL, action TEXT NOT NULL, source_type TEXT NOT NULL CHECK (source_type IN ('reflection','outcome','manual')), source_id TEXT, confidence REAL NOT NULL DEFAULT 0.50 CHECK (confidence BETWEEN 0.00 AND 1.00), status TEXT NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed','active','rejected','deprecated')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|completion_candidates|CREATE TABLE completion_candidates ( id TEXT PRIMARY KEY, workspace_id TEXT, task_id TEXT NOT NULL, repo_name TEXT, reason TEXT NOT NULL, evidence_refs TEXT NOT NULL DEFAULT '[]', confidence TEXT NOT NULL CHECK (confidence IN ('high','medium','low')), suggested_artifact TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','rejected','auto_applied')), detected_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), resolved_at TEXT )
table|concepts|CREATE TABLE concepts ( id TEXT PRIMARY KEY, workspace_id TEXT, title TEXT NOT NULL, content TEXT NOT NULL, tags TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), importance REAL NOT NULL DEFAULT 0.5, recall_count INTEGER NOT NULL DEFAULT 0, last_recalled_at TEXT, base_lambda REAL NOT NULL DEFAULT 0.1, archived_at TEXT )
table|decisions|CREATE TABLE decisions ( id TEXT PRIMARY KEY, workspace_id TEXT, project_id TEXT, repo_name TEXT, title TEXT NOT NULL, context TEXT NOT NULL, decision TEXT NOT NULL, rationale TEXT NOT NULL, alternatives TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), task_id TEXT, embedding_provider TEXT, embedding_model TEXT, embedding_dim INTEGER, source TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual','auto')) )
table|discipline_events|CREATE TABLE discipline_events ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, repo_name TEXT, tool_name TEXT NOT NULL, is_mutating INTEGER NOT NULL DEFAULT 0, observed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), linked_decision_id TEXT, workspace_id TEXT )
table|discipline_events_m8|CREATE TABLE discipline_events_m8 ( id TEXT PRIMARY KEY, workspace_id TEXT, event_type TEXT NOT NULL CHECK (event_type IN ( 'stuck_task', 'unlogged_decision', 'plan_no_task', 'proposal_fail', 'stale_handoff', 'repeated_correction', 'task_no_outcome', 'decision_no_reflection' )), severity TEXT NOT NULL DEFAULT 'warn' CHECK (severity IN ('info', 'warn', 'error')), detail TEXT NOT NULL DEFAULT 'null', resolved_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) )
table|evaluations|CREATE TABLE evaluations ( id TEXT PRIMARY KEY, workspace_id TEXT, outcome_id TEXT NOT NULL, analysis TEXT NOT NULL, lessons TEXT NOT NULL DEFAULT '[]', improvement_suggestions TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|goals|CREATE TABLE goals ( id TEXT PRIMARY KEY, workspace_id TEXT, title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','completed','archived')), area TEXT, due_date TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|knowledge_items|CREATE TABLE knowledge_items ( id TEXT PRIMARY KEY, workspace_id TEXT, type TEXT NOT NULL CHECK (type IN ('article','til','bookmark','zettelkasten')), title TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', url TEXT, tags TEXT NOT NULL DEFAULT '[]', embedding BLOB, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), source TEXT NOT NULL DEFAULT 'manual', learning_value INTEGER CHECK (learning_value BETWEEN 1 AND 5), importance REAL NOT NULL DEFAULT 0.5, recall_count INTEGER NOT NULL DEFAULT 0, last_recalled_at TEXT, base_lambda REAL NOT NULL DEFAULT 0.1, archived_at TEXT, parent_id TEXT DEFAULT NULL, heading_path TEXT DEFAULT NULL, heading_level INTEGER DEFAULT NULL, project_id TEXT DEFAULT NULL, task_id TEXT DEFAULT NULL, decision_id TEXT DEFAULT NULL )
table|knowledge_items_fts|CREATE VIRTUAL TABLE knowledge_items_fts USING fts5( title, content, content='knowledge_items', content_rowid='rowid', tokenize='porter unicode61' )
table|knowledge_items_fts_config|CREATE TABLE 'knowledge_items_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID
table|knowledge_items_fts_data|CREATE TABLE 'knowledge_items_fts_data'(id INTEGER PRIMARY KEY, block BLOB)
table|knowledge_items_fts_docsize|CREATE TABLE 'knowledge_items_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)
table|knowledge_items_fts_idx|CREATE TABLE 'knowledge_items_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID
table|memory_atoms|CREATE TABLE memory_atoms ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))),2) || '-' || substr('89ab', abs(random() % 4) + 1, 1) || substr(lower(hex(randomblob(2))),2) || '-' || lower(hex(randomblob(6)))), workspace_id TEXT, parent_table TEXT NOT NULL, parent_id TEXT NOT NULL, content TEXT NOT NULL, keywords TEXT NOT NULL DEFAULT '[]', tags TEXT NOT NULL DEFAULT '[]', created_at DATETIME NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), digest_status TEXT NOT NULL DEFAULT 'pending', error_msg TEXT )
table|memory_links|CREATE TABLE memory_links ( from_atom_id TEXT NOT NULL, to_atom_id TEXT NOT NULL, link_type TEXT NOT NULL CHECK (link_type IN ('same_entity','same_action','same_time','same_project')), confidence REAL NOT NULL DEFAULT 0.5 CHECK (confidence BETWEEN 0.0 AND 1.0), created_at DATETIME NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), PRIMARY KEY (from_atom_id, to_atom_id, link_type) )
table|merged_prs_observed|CREATE TABLE merged_prs_observed ( id TEXT PRIMARY KEY, workspace_id TEXT, repo TEXT NOT NULL, url TEXT NOT NULL, head_ref TEXT, title TEXT, body_excerpt TEXT, merged_at TEXT NOT NULL, observed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|outcomes|CREATE TABLE outcomes ( id TEXT PRIMARY KEY, workspace_id TEXT, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, result TEXT NOT NULL CHECK (result IN ('success','failure','partial','unknown','regressed')), metrics TEXT, notes TEXT, related_rule_ids TEXT NOT NULL DEFAULT '[]', work_session_id TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|pending_proposals|CREATE TABLE pending_proposals ( id TEXT PRIMARY KEY, workspace_id TEXT, type TEXT NOT NULL CHECK (type IN ('goal','project','task','concept','knowledge','playbook','decision')), payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted','rejected')), proposed_by TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), resolved_at TEXT, reason TEXT )
table|playbooks|CREATE TABLE playbooks ( id TEXT PRIMARY KEY, workspace_id TEXT, trigger_pattern TEXT NOT NULL, action_template TEXT NOT NULL, source_decision_ids TEXT NOT NULL DEFAULT '[]', confidence REAL NOT NULL DEFAULT 0.50, hits INTEGER NOT NULL DEFAULT 0, last_used_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|procedural_memories|CREATE TABLE procedural_memories ( id TEXT PRIMARY KEY, workspace_id TEXT, repo_name TEXT NOT NULL DEFAULT '', project_id TEXT, title TEXT NOT NULL, when_to_use TEXT NOT NULL DEFAULT '', approach_md TEXT NOT NULL DEFAULT '', tools_used TEXT NOT NULL DEFAULT '[]', files_touched TEXT NOT NULL DEFAULT '[]', success_count INTEGER NOT NULL DEFAULT 0, last_used_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|project_arch|CREATE TABLE project_arch ( id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, summary TEXT NOT NULL, file_map TEXT NOT NULL DEFAULT '{}', last_commit_sha TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|project_status_snapshots|CREATE TABLE project_status_snapshots ( id TEXT PRIMARY KEY, slug TEXT NOT NULL, workspace_id TEXT, generated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), sprint_summary TEXT, gap_analysis TEXT, sota_catchup_pct INTEGER, pending_summary TEXT, source_decision_ids TEXT NOT NULL DEFAULT '[]', embedding BLOB, embedding_provider TEXT, embedding_model TEXT, embedding_dim INTEGER, source TEXT NOT NULL DEFAULT 'auto-status-snapshot' )
table|projects|CREATE TABLE projects ( id TEXT PRIMARY KEY, workspace_id TEXT, goal_id TEXT, name TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','completed','archived','on_hold')), area TEXT NOT NULL DEFAULT 'projects', priority INTEGER NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 5), repo_name TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|reflections|CREATE TABLE reflections ( id TEXT PRIMARY KEY, workspace_id TEXT, type TEXT NOT NULL CHECK (type IN ('daily','weekly','task','decision', 'proposal','knowledge','system')), related_entity_type TEXT, related_entity_id TEXT, summary TEXT NOT NULL DEFAULT '', insights TEXT NOT NULL DEFAULT 'null', patterns_detected TEXT NOT NULL DEFAULT 'null', suggested_actions TEXT NOT NULL DEFAULT 'null', confidence REAL NOT NULL DEFAULT 0.0 CHECK (confidence BETWEEN 0.0 AND 1.0), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|repos|CREATE TABLE repos ( id TEXT PRIMARY KEY, workspace_id TEXT, name TEXT NOT NULL, path TEXT, description TEXT, language TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','archived','on_hold')), current_branch TEXT, known_issues TEXT NOT NULL DEFAULT '[]', next_planned_step TEXT, last_activity TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|review_schedule|CREATE TABLE review_schedule ( id TEXT PRIMARY KEY, workspace_id TEXT, concept_id TEXT NOT NULL, stability REAL NOT NULL DEFAULT 1.0, difficulty REAL NOT NULL DEFAULT 0.3, due_date TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), last_review_at TEXT, review_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|session_handoffs|CREATE TABLE session_handoffs ( id TEXT PRIMARY KEY, workspace_id TEXT, project_id TEXT, repo_name TEXT, intent TEXT NOT NULL, context_summary TEXT, resolved_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), summary_text TEXT, embedding BLOB, embedding_provider TEXT, embedding_model TEXT, embedding_dim INTEGER, next_actions TEXT NOT NULL DEFAULT '[]' )
table|skills|CREATE TABLE skills ( id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' || substr(lower(hex(randomblob(2))),2) || '-' || substr('89ab', abs(random() % 4) + 1, 1) || substr(lower(hex(randomblob(2))),2) || '-' || lower(hex(randomblob(6)))), workspace_id TEXT, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', triggers TEXT NOT NULL DEFAULT '[]', steps TEXT NOT NULL DEFAULT '[]', failure_modes TEXT NOT NULL DEFAULT '[]', verification_checklist TEXT NOT NULL DEFAULT '[]', examples TEXT NOT NULL DEFAULT '[]', source_atom_ids TEXT NOT NULL DEFAULT '[]', success_count INTEGER NOT NULL DEFAULT 0, failure_count INTEGER NOT NULL DEFAULT 0, last_used_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|tasks|CREATE TABLE tasks ( id TEXT PRIMARY KEY, workspace_id TEXT, project_id TEXT, title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','in_progress','completed','cancelled')), priority INTEGER NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 5), importance INTEGER CHECK (importance BETWEEN 1 AND 3), context TEXT, assignee TEXT, due_date TEXT, artifact TEXT, checklist TEXT NOT NULL DEFAULT '[]', kind TEXT NOT NULL DEFAULT 'general' CHECK (kind IN ('general','fix-pr','feature','refactor','research','chore')), branch_name TEXT, pr_url TEXT, commit_shas TEXT NOT NULL DEFAULT '[]', vision_item_id TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|vision_items|CREATE TABLE vision_items ( id TEXT PRIMARY KEY, workspace_id TEXT, repo_name TEXT, project_id TEXT, title TEXT NOT NULL, why_blocked TEXT NOT NULL, depends_on TEXT NOT NULL DEFAULT '[]', parent_initiative TEXT, status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','discussing','maturing','promoted','dismissed')), context_md TEXT, promoted_task_id TEXT, last_discussed_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|work_session_evidence|CREATE TABLE work_session_evidence ( id TEXT PRIMARY KEY, workspace_id TEXT, session_id TEXT NOT NULL, evidence_type TEXT NOT NULL CHECK (evidence_type IN ('command','pr','ci','railway','manual_note')), status TEXT NOT NULL CHECK (status IN ('passed','failed','unknown')), command TEXT, artifact TEXT, output_excerpt TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
table|work_session_tasks|CREATE TABLE work_session_tasks ( session_id TEXT NOT NULL, task_id TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('primary','follow_up','blocker','generated')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY (session_id, task_id) )
table|work_sessions|CREATE TABLE work_sessions ( id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, repo_name TEXT NOT NULL, project_id TEXT, title TEXT NOT NULL, goal TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ( 'planned','in_progress','checkpointed', 'completed','cancelled','archived')), source TEXT NOT NULL CHECK (source IN ('manual','confirm_plan','hook','other')), confirmed_plan_id TEXT NULL, current_task_id TEXT, final_summary TEXT NULL, started_at TEXT NULL, last_checkpoint_at TEXT NULL, completed_at TEXT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), context_pack_id TEXT NULL, verification_status TEXT NULL CHECK (verification_status IN ('not_run','passed','failed','unknown')), verification_command TEXT NULL, verification_output_excerpt TEXT NULL, outcome_id TEXT NULL, final_result TEXT NULL CHECK (final_result IN ('success','failure','partial','unknown','regressed')), branch_name TEXT NULL )
table|workspace_preferences|CREATE TABLE workspace_preferences ( workspace_id TEXT PRIMARY KEY, model_preference TEXT NOT NULL DEFAULT 'claude-sonnet-4-6', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) )
trigger|knowledge_items_ad|CREATE TRIGGER knowledge_items_ad AFTER DELETE ON knowledge_items BEGIN INSERT INTO knowledge_items_fts(knowledge_items_fts, rowid, title, content) VALUES ('delete', old.rowid, old.title, old.content); END
trigger|knowledge_items_ai|CREATE TRIGGER knowledge_items_ai AFTER INSERT ON knowledge_items BEGIN INSERT INTO knowledge_items_fts(rowid, title, content) VALUES (new.rowid, new.title, new.content); END
trigger|knowledge_items_au|CREATE TRIGGER knowledge_items_au AFTER UPDATE ON knowledge_items BEGIN INSERT INTO knowledge_items_fts(knowledge_items_fts, rowid, title, content) VALUES ('delete', old.rowid, old.title, old.content); INSERT INTO knowledge_items_fts(rowid, title, content) VALUES (new.rowid, new.title, new.content); END
